@'
import fs from 'node:fs';
import path from 'node:path';
import assert from 'node:assert/strict';
import {parseManifest} from './packages/core/src/domain/manifest.ts';
import {parseSkillDocument, documentName, documentDescription} from './packages/core/src/domain/skill-document.ts';
const dir='skills/sql-server-performance';
const {manifest,issues}=parseManifest(fs.readFileSync(dir+'/skill.yaml','utf8'),{source:dir+'/skill.yaml',strict:true});
assert.deepEqual(issues,[]);
const main=fs.readFileSync(dir+'/SKILL.md','utf8'), doc=parseSkillDocument(main);
assert.equal(documentName(doc),manifest.name);
assert.equal(documentDescription(doc),manifest.description);
assert.equal(manifest.version,'1.0.4');
const files=fs.readdirSync(dir,{recursive:true}).filter(x=>fs.statSync(path.join(dir,x)).isFile());
assert.deepEqual(files.map(x=>x.replaceAll('\\','/')).sort(),['SKILL.md','references/concurrency-plans-instance.md','references/jdbc-and-operations.md','references/storage-indexes-statistics.md','skill.yaml']);
for(const file of manifest.files) assert.ok(fs.existsSync(path.join(dir,file)),file);
const referrals=[...manifest.dependencies.map(x=>x.name),...manifest.suggests];
for(const name of referrals) assert.ok(fs.existsSync(path.join('skills',name,'SKILL.md')),name);
let relativeLinks=0;
for(const file of files.filter(x=>x.endsWith('.md'))) {
 const text=fs.readFileSync(path.join(dir,file),'utf8');
 for(const [,ref] of text.matchAll(/\[[^\]]*\]\(([^)]+)\)/g)) if(!/^[a-z]+:\/\//i.test(ref)&&!ref.startsWith('#')) {
  assert.ok(fs.existsSync(path.resolve(dir,path.dirname(file),ref.split('#')[0])),ref); relativeLinks++;
 }
}
for(const file of files.filter(x=>x.startsWith('references'))) assert.ok(main.includes(file.replaceAll('\\','/')),file);
console.log(JSON.stringify({strictManifestIssues:issues.length,files:files.length,metadataEqual:true,version:manifest.version,relativeLinks,declaredReferrals:referrals.length,routes:'pass'}));
'@ | node --input-type=module -
